def fix_spaces(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == ' ':
            if i + 1 < len(text) and text[i + 1] == ' ':
                if i + 2 < len(text) and text[i + 2] == ' ':
                    result.append('-')
                    i += 3
                else:
                    result.append('-')
                    i += 2
            else:
                result.append('_')
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result) 
